arguments.file_text:
#:property AllowUnsafeBlocks=true

Span<nint> nints = stackalloc nint[4];
for (int i = 0; i < nints.Length; i++)
    nints[i] = i * 10;

Span<nuint> nuints = stackalloc nuint[4];
for (int i = 0; i < nuints.Length; i++)
    nuints[i] = (nuint)(i * 100);

Console.WriteLine($"nint span length: {nints.Length}, element size: {nint.Size} bytes");
foreach (var n in nints)
    Console.Write($" {n}");
Console.WriteLine();

Console.WriteLine($"nuint span length: {nuints.Length}, element size: {nuint.Size} bytes (same as IntPtr.Size: {IntPtr.Size})");
foreach (var n in nuints)
    Console.Write($" {n}");
Console.WriteLine();

